arguments.cmd:
cat > /tmp/groove_test.scad <<'EOF'
W_in=32.4; groove_d=1.6; gb=17.0; ce_in=19.4; ce_out=21.0; groove_y0=2.0; L_out=67.0;
module groove_void_left() {
    x_in = -W_in/2; x_out = -W_in/2 - groove_d; y0 = groove_y0; y1 = L_out + 0.1;
    polyhedron(
        points = [
            [x_in, y0, gb], [x_out, y0, gb],
            [x_out, y0, ce_out], [x_in, y0, ce_in],
            [x_in, y1, gb], [x_out, y1, gb],
            [x_out, y1, ce_out], [x_in, y1, ce_in]
        ],
        faces = [[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7],[0,3,2,1],[4,5,6,7]]
    );
}
groove_void_left();
EOF
OPENSCAD_BIN=/usr/local/bin/openscad; /usr/local/bin/openscad -o /tmp/groove_test.stl /tmp/groove_test.scad 2>&1; python3 -c "
import trimesh
m = trimesh.load('/tmp/groove_test.stl')
print('watertight:', m.is_watertight, 'volume:', m.volume)
print('bounds:', m.bounds)
"
